pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address depositor, uint256 depositAmount, uint256 cashOutAmount) public {
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this) && depositor != address(c));
        vm.assume(depositAmount > 1 ether);
        vm.assume(cashOutAmount <= depositAmount);

        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        uint256 balBefore = c.balances(depositor);
        uint256 contractBefore = address(c).balance;

        vm.prank(depositor);
        bool ok = true;
        try c.CashOut(cashOutAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            uint256 balAfter = c.balances(depositor);
            uint256 contractAfter = address(c).balance;
            int256 sumChange = int256(balAfter - balBefore) + int256(contractAfter - contractBefore);
            assertTrue(sumChange >= 0);
        } else {
            assertTrue(true);
        }
    }
}

