pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address addr, uint256 depositAmt, uint256 cashOutAmt) public {
        // Restrict to reasonable nonzero amounts and valid address
        vm.assume(addr != address(0));
        depositAmt = bound(depositAmt, 1 ether + 1, 1000 ether);
        cashOutAmt = bound(cashOutAmt, 1, 1000 ether);

        // Fund addr and make a deposit
        vm.deal(addr, depositAmt);
        vm.prank(addr);
        c.Deposit{value: depositAmt}();

        // Record balance before cash out
        uint256 balanceBefore = c.balances(addr);

        // If the recorded balance is zero, we cannot test a full cash out; skip
        vm.assume(balanceBefore > 0);
        // Also ensure we only attempt cash out up to the recorded balance
        vm.assume(cashOutAmt <= balanceBefore);

        vm.prank(addr);
        c.CashOut(cashOutAmt);

        uint256 balanceAfter = c.balances(addr);
        // Reference: balanceAfter == balanceBefore - cashOutAmt (always)
        // Bug: Deposit subtracted, so balanceBefore is smaller than deposit, cash out may revert or leave wrong balance
        // Since we assume cashOutAmt <= balanceBefore, the reference always succeeds and reduces balance correctly.
        // The invariant: after CashOut, the new balance equals old balance minus requested amount.
        assertTrue(balanceAfter == balanceBefore - cashOutAmt);
    }
}

