pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep amount within reasonable bounds to avoid overflow but wide enough to trigger bug
        vm.assume(depositor != address(0));
        vm.assume(amount > c.MinDeposit() && amount < 1e28);

        uint256 balanceBefore = c.balances(depositor);

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.Deposit{value: amount}();

        uint256 balanceAfter = c.balances(depositor);

        // For reference C: balanceAfter == balanceBefore + amount (strictly greater than before)
        // For mutant: balanceAfter == balanceBefore - amount (violates the invariant, fails when amount > 0)
        assertTrue(balanceAfter > balanceBefore);
    }
}

