pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 cashoutAmount) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > c.MinDeposit());
        vm.assume(cashoutAmount > 0);
        vm.assume(cashoutAmount <= depositAmount);

        uint256 initialContractBal = address(c).balance;

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 contractBalAfterDeposit = address(c).balance;

        vm.prank(actor);
        try c.CashOut(cashoutAmount) { } catch { }

        uint256 finalContractBal = address(c).balance;

        // After a deposit and a successful (non-reverting) cashout, the contract's ether balance
        // must equal initial + deposit - cashout. The mutant's deposit subtracts instead of adds
        // to internal balances, potentially causing the cashout to revert or leave the contract
        // with more ether than it should have if the cashout succeeds.
        assertTrue(finalContractBal <= initialContractBal + depositAmount - cashoutAmount);
    }
}

